mapper.insert:

	SELECT category_idx 
	FROM file_category 
	WHERE category_code = #{categoryCode} 


INSERT INTO uploaded_file ( 
	-- file_id
	post_id
	, category_idx
	, origin_name
	, stored_name
	, file_path
	, file_size
	, file_ext
	, reg_date ) VALUES 

	(
		#{postId}
		, #{category_idx}
		, #{file.originName}
		, #{file.storedName}
		, #{file.filePath}
		, #{file.fileSize}
		, #{file.fileExt}
		, NOW()
	)
